 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    pairs = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    pairs.add((r, c, dr, dc, color))
    for r, c, dr, dc, color in pairs:
        for sign in (-1, 1):
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] != color and grid[rr][cc] != background:
                    break
                if grid[rr][cc] == background:
                    out[rr][cc] = color
                rr += sign * dr
                cc += sign * dc
    return out
